// Dependencies supplied by the original C headers: prm44xx_54xx.h and prm.h.

pub const OMAP4430_PRM_BASE: usize = 0x4a306000;

// Equivalent of OMAP2_L4_IO_ADDRESS(OMAP4430_PRM_BASE + inst + reg).
pub unsafe fn omap44xx_prm_regaddr(inst: usize, reg: usize) -> usize {
    OMAP2_L4_IO_ADDRESS(OMAP4430_PRM_BASE + inst + reg)
}

